target.css:
:root {
  --ink: #22243d;
  --muted: #6f7088;
  --paper: #fffdf8;
  --line: #dadbea;
  --lavender: #ece9ff;
  --violet: #6256b2;
  --mint: #ddf3e7;
  --green: #287557;
  --coral: #ffe2db;
  --coral-ink: #a14736;
}

.rehearsal-card {
  box-sizing: border-box;
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 16px 18px 12px;
}

.title-block {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.eyebrow {
  margin: 0;
  color: var(--violet);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 23px;
  font-weight: 750;
  letter-spacing: -0.04em;
  line-height: 1;
}

.status {
  margin: 0;
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--green);
  font-size: 12px;
  font-weight: 700;
}

.meta-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0 18px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.meta-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  padding: 9px 10px;
  border-right: 1px solid var(--line);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.15;
}

.meta-item:first-child {
  padding-left: 0;
}

.meta-item:last-child {
  border-right: 0;
}

.meta-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.run-grid {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  gap: 12px;
  padding: 12px 18px;
}

.score-panel {
  box-sizing: border-box;
  min-height: 104px;
  margin: 0;
  padding: 11px;
  border-radius: 12px;
  background: var(--lavender);
}

.score-panel figcaption,
.call-panel h2 {
  margin: 0;
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.score-panel figcaption {
  color: var(--violet);
}

.phrase-strip {
  display: flex;
  gap: 5px;
  margin: 9px 0 8px;
}

.phrase {
  display: grid;
  width: 26px;
  height: 22px;
  place-items: center;
  border: 1px solid var(--violet);
  border-radius: 6px;
  color: var(--violet);
  font-size: 11px;
  font-weight: 750;
}

.phrase.active {
  background: var(--violet);
  color: var(--paper);
}

.score-note {
  margin: 0;
  color: var(--ink);
  font-size: 12px;
  font-weight: 650;
  line-height: 1.3;
}

.call-panel {
  padding: 2px 0 0;
}

.call-panel h2 {
  color: var(--muted);
}

.cues {
  display: grid;
  gap: 4px;
  margin: 7px 0 0;
  padding: 0;
  list-style: none;
}

.cues li {
  display: grid;
  grid-template-columns: 45px 1fr;
  align-items: center;
  gap: 7px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--line);
}

.cue-time {
  color: var(--green);
  font-size: 12px;
  font-weight: 750;
}

.cue-text {
  font-size: 13px;
  font-weight: 650;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 18px;
  background: var(--coral);
}

.card-footer p {
  margin: 0;
  color: var(--coral-ink);
  font-size: 12px;
  font-weight: 650;
}

button {
  border: 0;
  border-radius: 8px;
  padding: 7px 12px;
  background: var(--coral-ink);
  color: var(--paper);
  font-size: 12px;
  font-weight: 750;
}

